INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('roleMaxLevel', 1000000, '角色等级上限（1..1000000；每级数值由「等级曲线」4 条 × 6 段决定）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('expGain.expPerLevel', 5, '每级基准经验：同级击杀经验 = (怪物等级+1) × 该值', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('expGain.maxLevelGap', 6, '角色与怪物等级差达到该值（含）后不再获得经验', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('mpRecoverPerSecond', 2, '魔法值自然回复速度（点 / 秒，0 = 关闭自然回蓝；由服务端结算，客户端读快照同步）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('soakExpPerTick', 0, '泡点活动：在线角色每拍获得的经验（0 = 活动关闭；服务端定时发放，走击杀同一套升级链路）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('soakTickSeconds', 10, '泡点活动：发经验的拍间隔（秒；与上一条配合出「每 M 秒发 N 点」的速率）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('critRate', 0, '角色基础暴击率（0~1；与技能自带的暴击率相加。出厂 0 = 新号不暴击）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('critDamage', 1.5, '角色基础暴击倍率（> 1 才生效；技能配了自己的倍率则以技能为准。出厂 1.5 倍）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('attrPointRatio', 0.005, '属性点：每点加成系数（出厂 0.005 = 每点 0.5%）。力量→物攻、体质→生命+物防、精神→法攻+道攻+法力按等级曲线基础值的百分比放大；敏捷→暴击率按绝对百分点加（0.005 = +0.5%）', 0);
INSERT INTO "growth_scalars" ("key", "value", "description", "updated_at") VALUES ('attrResetCost', 500, '属性点：洗点花费的绑定元宝（0 = 免费洗点。四维归零、已分配点数全部退还）', 0);
INSERT INTO "guide_settings" ("id", "steps", "updated_at") VALUES (1, '[{"id":"move","title":"先动起来","desc":"拖住左下角的摇杆走两步；电脑上也可以按住方向键或点地面。","spot":"joystick","trigger":"move"},{"id":"fight","title":"打一只怪","desc":"走近怪物，点下面的技能（或按 1~6）就能出手。","spot":"shortcut","trigger":"kill"},{"id":"loot","title":"把掉落捡起来","desc":"怪死了会掉东西，走上去就会自动拾取，东西直接进背包。","spot":"nav:bag","trigger":"pickup"},{"id":"bag","title":"看看背包","desc":"刚捡的装备和药都在这里：点格子看详情，装备可以直接穿上。","spot":"nav:bag","trigger":"openBag"},{"id":"skill","title":"认识你的技能","desc":"技能列表里有全部技能和解锁等级，拖到快捷栏就能随时用。","spot":"nav:skill","trigger":"openSkill"},{"id":"social","title":"别一个人玩","desc":"聊天分世界 / 帮会 / 私聊三页；任务在左边的追踪栏，点一下就能打开任务面板。","spot":"nav:chat","trigger":"openChat"}]', 0);
